INSERT INTO `primary_para` VALUES (1,'MEMORY_POOL',500,64,67108864,'共享内存池大小，以M为单位。共享内存池是由DM管理的内存。有效值范围：32位平台为（64~2000），64位平台为 （64~67108864）'),(2,'MEMORY_TARGET',15000,0,67108864,'共享内存池在扩充到此大小以上后，空闲时收缩回此指定大小，以M为单位，有效值范围：32位平台为（0~2000）， 64位平台为（0~67108864），0表示不限制'),(3,'MEMORY_EXTENT_SIZE',1,1,10240,'共享内存池每次扩充的大小，以 M 为单位'),(4,'HUGE_MEMORY_PERCENTAGE',50,1,100,'指示 HUGE_BUFFER 中可以借用作常规内存分配的空间百分比'),(5,'HUGE_BUFFER',80,80,1048576,'HUGE 表使用的缓冲区大小，以 M 为单位。'),(6,'HUGE_BUFFER_POOLS',4,1,512,'HUGE BUFFER 系统分区数，每个 HUGE BUFFER 分区的大小为 HUGE_BUFFER/HUGE_BUFFER_POOLS。'),(7,'BUFFER',1000,8,1048576,'系统缓冲区大小，以 M 为单位。'),(8,'BUFFER_POOLS',19,1,512,'BUFFER 系统分区数，每个 BUFFER 分区的大小为 BUFFER/BUFFER_POOLS。'),(9,'FAST_POOL_PAGES',3000,0,99999999,'快速缓冲区页数。FAST_POOL_PAGES 的值最多不能超过 BUFFER 总页数的一半，如果超过，系统会自动调整为 BUFFER 总页数的一半。'),(10,'FAST_ROLL_PAGES',1000,0,9999999,'BUFFER 中 FAST POOL 回滚页数量，最多不超过 FAST_POOL_PAGES 的 75%，如果超过，系统会自动调整。'),(11,'RECYCLE',300,8,1048576,'RECYCLE 缓冲区大小，以 M 为单位。'),(12,'RECYCLE_POOLS',19,1,512,'RECYCLE 缓冲区分区数。有效值范围（1~512）。一般情况下，每个 RECYCLE 分区的大小为 RECYCLE/RECYCLE_POOLS，但系统也会自动校正 RECYCLE 缓冲区分区数，以保证每个分区中数据页不少于 3000 页'),(13,'SORT_BUF_SIZE',20,1,2048,'原排序机制下，排序缓存区最大值，以 M 为单位。'),(14,'HJ_BUF_GLOBAL_SIZE',5000,10,500000,'HASH 连接操作符的数据总缓存大小（>= HJ_BUF_SIZE），系统级参数，以 M 为单位。'),(15,'HJ_BUF_SIZE',1000,2,100000,'单个 HASH 连接操作符的数据总缓存大小，以 M 为单位，必须小于 HJ_BUF_GLOBAL_SIZE。'),(16,'HJ_BLK_SIZE',2,1,50,'HASH 连接操作符每次分配缓存（BLK）大小，以 M 为单位，必须小于 HJ_BUF_SIZE。'),(17,'HAGR_BUF_GLOBAL_SIZE',5000,10,1000000,'HAGR、DIST、集合操作、SPL2、NTTS2 以及 HTAB 操作符的数据总缓存大小（>= HAGR_BUF_SIZE），系统级参 数，以 M 为单位。'),(18,'HAGR_BUF_SIZE',500,2,500000,'单个 HAGR、DIST、集合操作、SPL2、NTTS2 以及 HTAB 操作符的数据总缓存大小，以 M 为单位。如 果 HAGR_BUF_SIZE 设 置 的 值 满 足 范 围 且 大 于 HAGR_BUF_GLOBAL_SIZE ， 那 么 会 在\nHAGR_BUF_GLOBAL_SIZE/2 和 500000 两个值中，选出较小的那个，作为新的 HAGR_BUF_SIZE 值。'),(19,'HAGR_BLK_SIZE',2,1,50,'HAGR、DIST、集合操作、SPL2、NTTS2 以及 HTAB 操作符每次分配缓存（BLK）大小，以 M 为单位，必须小于 HAGR_BUF_SIZE。'),(20,'DICT_BUF_SIZE',50,1,2048,'字典缓冲区大小，以 M 为单位'),(21,'VM_POOL_SIZE',64,32,1024,'系统执行时虚拟机内存池大小，以 KB 为单位，在执行过程中用到的内存大部分是从这里申请的，它的空间是从操作 系统中直接申请的。'),(22,'VM_POOL_TARGET',16384,0,10,'虚拟机内存池能扩充到的最大大小，以 KB 为单位，0 表示不限制'),(23,'SESS_POOL_SIZE',64,16,1024,'会话缓冲区大小，以 KB 为单位，若所申请的内存超过实际能申请的大小，则系统\n将按 16KB 大小重新申请。'),(24,'SESS_POOL_TARGET',16384,0,10,'会话缓冲区能扩充到的最大大小，以 KB 为单位，0 表示不限制。'),(25,'VM_MEM_HEAP',0,0,2,'VM 是否使用 HEAP 分配内存。0：MEMORY POOL 模式；1：HEAP 模式；2：MEMORY POOL 和 HEAP 混合模式'),(26,'WORKER_THREADS',16,1,64,'工作线程的数目'),(27,'FAST_RW_LOCK',1,0,2,'快速读写锁标记，0 不启用；1 表示只有 FAST POOL 启用，2 表示所有 POOL 都启用'),(28,'WORK_THRD_STACK_SIZE',8192,1024,32768,'工作线程堆栈大小，以 KB 为单位。'),(29,'WORK_THRD_RESERVE_SIZE',200,200,1024,'工作线程预留栈帧大小，以 KB 为单位。'),(30,'LIKE_OPT_FLAG',127,0,127,'LIKE 查询的优化开关。0：不优化；1：对于 LIKE 表达式首尾存在通配符的情况，优化为 POSITION()函数； 对于 LIKE 表达式首部存在通配符，并且条件列存在 REVERSE()函数索引时，优化为 REVERSE()函数；2： 对于 COL1 LIKE COL2 || \'%\'的情况，如果 COL1 上没有索引，则优化为 POSITION()函数；如果 COL1 上有索引，则优化为 BETWEEN..AND 条件；4：对于 COL1 LIKE ‗A‘||‗B%‘的情况，优化为 COL1 LIKE ‗AB%‘； 8：对于可计算的 LIKE 表达式，优化为常量；16：对于控制函数索引列的 LIKE 表达式，优化为 BETWEEN..AND 条件；32：将 LIKE ESCAPE 表达式转换为 BETWEEN..AND 条件，尽可能使用索引；64：在取值为 2 的基础 上，对于 COL1 LIKE COL2 || \'%\'的情况，如果 COL1 上有索引，则优化为 BETWEEN..AND 条件的同时保 留 LIKE 表达式。 支持使用上述有效值的组合值，如 31 表示同时进行 1、2、4、8 和 16 的优化'),(31,'UPD_DEL_OPT',2,0,2,'删除更新计划优化方式，取值范围 0、1、2 单节点计划，0：不优化 1，2:都可优化 NTTS MPP 计划，0：不优化； 1：优化删除更新计划，不优化 NTTS；2：优化删除更新计划，同时优化 NTTS'),(32,'GROUP_OPT_FLAG',4,0,63,'分组项优化参数开关。0：不优化；1：非 MYSQL 兼容模式下（即 COMPATIBLE_MODE 不等于 4），支持查询 项不是 GROUP BY 表达式；2：外层分组项下放到内层派生表中提前分组优化；4：表示对于多级分区，并行下允许尝试不生成多个 AGR；8：进行哈希分组时，依赖分组项列中的核心项分组列来分组；16：位图索引覆盖\n简单分组查询中的所有列时，允许使用位图索引对查询进行优化；32：进行哈希分组时，对 TOP 查询进行优化，\n提前返回指定数量的分组。\n支持使用上述有效值的组合值，如 3 表示同时进行 1 和 2 的优化'),(33,'CASE_WHEN_CVT_IFUN',9,0,15,'对 CASE WHEN 查询表达式的优化处理。0：不优化；1：将 CASE WHEN 查询表达式转换为 IFOPERATOR 函数；\n2：将 CASE WHEN 查询表达式转换为 IFOPERATOR 函数，且有限制地进行表达式重用；4：CASE WHEN 查询\n表达式在运算符中转换为 OR 进行处理；8：对于 CASE WHEN 查询表达式不考虑 THEN…ELSE 表达式重用\n支持使用上述有效值的组合值，如 5 表示同时进行 1 和 4 的优化'),(34,'OUTER_CVT_INNER_PULL_UP_COND_FLAG',3,1,3,'控制外连接转化内连接的优化。 1：当外连接转化为内连接时，打开连接条件。 2：转化时探测 OR 布尔表达式是否能优化。即探测 OR 的每个分支中是否隐式包含 IS NOT NULL 的条件，若是则也转为内连接。\n支持使用上述有效值的组合值，如 3 表示同时进行 1 和 2 的优化'),(35,'REFED_SUBQ_CROSS_FLAG',1,0,1,'是否将相关子查询与外层表优化为 CROSS JOIN，0：不优化；1：优化。注：DM 早期版本参数，不再推荐使用'),(36,'NONREFED_SUBQUERY_AS_CONST',0,0,1,'是否将非相关子查询转化为常量处理。0：不进行优化，对非相关子查询使用连接方式处理；1：将非相关子查 询转换为常量，作为过滤条件使用。'),(37,'INDEX_SKIP_SCAN_RATE',0.0025,0,1,'复合索引跳跃扫描的代价调节开关。当列的 （DISTINCT 数/总行数）比值大于该值时，就不再使用索引跳跃 扫描的方式。'),(38,'SPEED_SEMI_JOIN_PLAN',9,0,31,'是否加速半连接的探测过程。 0：不加速； 1：加速计划探测； 2：加速计划探测和执行； 4：调整 DISTINCT 代价估算，期望更接近实际情况，有利于计划选择。4 支持的场景如下： 1)控制半连接转换内连接，生成的 DISTINCT 代价估算； 2)控制普通 DISTINCT 代价计算 8：SEMI 规则优化增加处理右孩子包含 SLCT 的情况； 16：SEMI 探测消除 SORT 优化时多探测一次 HRS 的情况'),(39,'COMPLEX_VIEW_MERGING',0,0,2,'对于复杂视图（一般含有 GROUP 或者集函数等）会执行合并操作，使得 GROUP 分组操作在连接之后才执行。\n0：不启用；1：对不包含别名和同名列的视图进行合并；2：视图定义包含别名或同名列时也进行合并'),(40,'ADAPTIVE_NPLN_FLAG',3,0,3,'是否启用自适应计划机制，仅 OPTIMIZER_MODE=1 时生效。0：不启用；1：对索引连接、嵌套含 VAR 连接 等复杂连接启用自适应计划；2：ORDER BY 在 HASH 连接时启用自适应计划；3：同时启用 1 和 2 的优化机制'),(41,'NBEXP_OPT_FLAG',7,0,7,'控制布尔表达式的一些优化。0：不优化；1：进行根据展开后的项数控制 NOT 是否下放展开的优化；2：进行 AND 分支的 OR 布尔表达式的公因子上拉优化；4：探测移除和派生表/实体视图内层一样的外层过滤条件。'),(42,'VIEW_FILTER_MERGING',138,0,511,'是否对视图条件进行优化以及如何优化。 0：不优化； 1：尽可能地进行视图条件合并； 2：自动判断是否进行视图条件合并； 4：视图包含分析函数时，如果分析函数的 PARTITION BY 具有唯一性，则外层过滤条件下推到视图内部； 8：如果派生表存在集函数，则不进行条件下推优化； 16：收集公用表达式相关的所有过滤条件，改写合并所有条件，并下放到公用表达式的内部；32：TOP 信息下 放至派生表内部； 64：外层表达式扩展视图内部 IS NOT NULL 过滤条件； 128：外层 ROWNUM 过滤条件转为内层 TOP 子句； 256：满足条件时，对相关派生表过滤条件进行下推优化。'),(43,'HASH_PLL_OPT_FLAG',0,0,63,'当进行 HASH SEMI/INNER 连接且右表为分区表时，控制是否对分区表连接进行优化以及优化的方式。 0：不进行分区表连接优化； 1：允许 HI/HRS 进行分区裁剪优化； 2：单个分区列的一级分区等值查询优化； 4：若为 ANTI SEMI 连接，则不允许使用 INDEX JOIN； 8：索引连接支持非等值 KEY 作为 PLL 的 KEY； 16：分区表根据子表数目粗略调整代价； 32：分析阶段根据 KEY 和扫描方式获得准确数据行数，精准计算 PLL 代价'),(44,'CKPT_RLOG_SIZE',128,0,4294967294,'产生多大日志文件后做检查点，以 M 为单位。'),(45,'CKPT_DIRTY_PAGES',0,0,4294967294,'产生多少脏页后产生检查点，以页为单位。有效值范围'),(46,'CKPT_INTERVAL',180,0,2147483647,'指定检查点的时间间隔。以秒为单位，为 0 时表示不自动定时做检查点。'),(47,'CKPT_FLUSH_RATE',5,0,100,'检查点刷盘比例'),(48,'CKPT_FLUSH_PAGES',1000,1000,100000,'检查点刷盘的最小页数。'),(49,'CKPT_WAIT_PAGES',1024,1,65534,'检查点一次发起的最大写入页数，等待这些页写入磁盘完成、调整检查点信息后，再发起新的刷盘请求，避免过于集中发起写磁盘请求，操作系统 IO 压力过大，导致 IO 性能下降。有效值范围'),(50,'FORCE_FLUSH_PAGES',8,0,1000,'调度线程启动刷脏页流程时，每个 BUFFER POOL 写入磁盘的脏页数'),(51,'DIRECT_IO',0,0,2,'非 WINDOWS 下有效，0：使用 OS 文件系统缓存；1：不使用 OS 文件系统缓存，采用系统模拟的异步 IO，异步 IO 的线程数由 IO_THR_GROUP 控制；2：不使用 OS 文件系统缓存，采用系统提供的 NATIVE AIO 机制，要求 LINUX 内核 2.6 以上'),(52,'IO_THR_GROUPS',8,1,512,'非 WINDOWS 下有效，表示 IO 线程组个数。'),(53,'HIO_THR_GROUPS',2,1,512,'HUGE 缓冲区 IO 线程组数目。'),(54,'TRX_VIEW_SIZE',512,16,65000,'事务视图中本地事务 ID 的缓存初始化个数。'),(55,'TRX_VIEW_MODE',1,0,1,'控制 MVCC 事务可见性判断的方式。0：事务启动前收集当前时刻的活动事务 ID 构造可见性视图，以确定 某一特定事务是否对当前事务可见；1：系统维护事务提交历史，以此判断事务可见性 注：DMDSC 环境下，TRX_VIEW_MODE 被强制设置为 0'),(56,'BDTA_SIZE',300,1,10000,'BDTA 缓存的记录数。'),(57,'JOIN_HASH_SIZE',500000,1,250000000,'HASH JOIN 操作时，HASH 表大小，以 CELL 个数为单位。'),(58,'CACHE_POOL_SIZE',100,1,67108864,'SQL 缓冲池大小，以 M 为单位。'),(59,'PHC_MODE_ENFORCE',0,0,15,'控制连接的实现方式。0：优化器根据代价情况自由选择连接方式；1：考虑使用 NEST LOOP INNER JOIN； 2：考虑使用索引连接；4：考虑使用哈希连接；8：考虑使用归并连接 支持使用上述有效值的组合值，如 6 表示优化器根据代价情况在索引连接和哈希连接间进行选择。 当参数值不为 0 或 15 且包含 2/4/8 其中之一或者它们的组合值时，会将包含的值对应的连接模式参数置 为 1 ， 没 有 包 含 的 值 对 应 的 连 接 模 式 参 数 置 为 0 （ 2 对 应 ENABLE_INDEX_JOIN ， 4 对 应 ENABLE_HASH_JOIN，8 对应 ENABLE_MERGE_JOIN）。例如，取值为 6 时没有包含 8，则会将 ENABLE_INDEX_JOIN 和 ENABLE_HASH_JOIN 置为 1，将 ENABLE_MERGE_JOIN 置为 0（仅强制设置 内存中的值，不改变 dm.ini 文件中的值）'),(60,'ENABLE_HASH_JOIN',1,0,1,'是否允许使用哈希连接，0：不允许；1：允许。'),(61,'ENABLE_INDEX_JOIN',1,0,1,'是否允许使用索引连接，0：不允许；1：允许。'),(62,'ENABLE_MERGE_JOIN',1,0,1,'是否允许使用归并连接，0：不允许；1：允许'),(63,'OPTIMIZER_AGGR_GROUPBY_ELIM',1,0,1,'当对派生视图进行分组查询，且分组项是派生视图分组项的子集时，是否考虑将两层分组进行合并。0：不 优化；1：将两层分组进行合并'),(64,'ENABLE_IN_VALUE_LIST_OPT',6,0,15,'是否允许 IN LIST 表达式优化。0：不优化。1：将 IN LIST 表达式在语义分析阶段优化为 CONSTV 处理； 2：在查询计划确定后，把 IN LIST 表达式转化为 CONSTV；4：允许 IN LIST 参与等值传递；8：从 IN VALUE 中构造出范围条件（仅限于 HUGE 表） 支持使用上述有效值的组合值，如 3 表示同时进行 1 和 2 的优化'),(65,'ENHANCED_BEXP_TRANS_GEN',3,0,3,'0：不允许非等值布尔表达式和外连接 ON 条件中的传递闭包；1：允许非等值布尔表达式和外连接 ON 条件 中的传递闭包；2：分析阶段针对表达式通过传递闭包产生的表达式进行去重处理'),(66,'FIRST_ROWS',100,1,1000000,'结果集一个消息中返回的最大行数'),(67,'BTR_SPLIT_MODE',0,0,1,'B 树叶子节点分裂方式，0：按对半分裂；1：在插入点进行分裂'),(68,'DECIMAL_FIX_STORAGE',0,0,1,'是否将长度为 1~18 的 DECIMAL/DEC 类型转换为定长方式存储。0：否；1：是。 若转换为定长存储，则 DECIMAL(P,S)的转换规则为：当 0<P<=P'),(69,'RLOG_BUF_SIZE',1024,1,20480,'单个日志缓冲区大小（以日志页个数为单位），取值只能为 2 的次幂值'),(70,'RLOG_POOL_SIZE',256,1,4096,'最大日志缓冲区大小（以 M 为单位）'),(71,'RLOG_PARALLEL_ENABLE',0,0,2,'是否启动并行日志。0：不启用，但是日志刷盘时可能合并为并行日志包刷盘；1：启用；2：一律不生成并行日志包'),(72,'FAST_RELEASE_SLOCK',1,0,1,'是否启用快速释放 S 锁，1：启用；0：不启用'),(73,'NOWAIT_WHEN_UNIQUE_CONFLICT',0,0,1,'插入数据时，如果和未提交数据有 UNIQUE 约束的冲突，是否等待未提交事务结束，0：等待，直至未提交事 务结束；1：不等待，立即返回错误'),(74,'UNDO_EXTENT_NUM',4,1,8192,'表示系统启动时，为每个工作线程分配的回滚簇个数。'),(75,'UNDO_RETENTION',90,0,86400,'事务提交后回滚页保持时间，单位为秒。注：类型为 DOUBLE，可支持毫秒'),(76,'PARALLEL_PURGE_FLAG',0,0,1,'是否启用并行事务清理，0：不启用；1：启用'),(77,'PURGE_WAIT_TIME',500,0,60000,'检测到系统清理动作滞后（待清理事务提交时间-当前系统时间>UNDO_RETENTION）情况下，系统等待时间 （MS）。有效范围（0 ~ 60000）， 0 表示不等待'),(78,'PSEG_RECV',3,0,3,'系统故障重启时，对活动事务和已提交事务的处理方式。0：跳过回滚活动事务和 PURGE 已经提交事务的步 骤。在回滚表空间出现异常、损坏、系统无法正常启动时，可将 PSEG_RECV 设置为 0，让系统启动；但存在 一定风险，未提交事务的修改将无法回滚，破坏事务的原子性；另外，已提交未 PURGE 的事务，将导致部分 存储空间无法回收；1：回滚活动事务并 PURGE 已经提交事务；2：延迟 PURGE 已提交事务，延迟回滚活动 事务；3：回滚活动事务，延迟 PURGE 已提交事务'),(79,'LOCK_DICT_OPT',2,0,2,'DICT封锁优化，事务提交或回滚时，不真正释放表上IS锁和IX锁对象。0:不优化；1:单机环境优化，DSC 集群环境不优化；2:单机、集群环境都优化'),(80,'MSG_COMPRESS_TYPE',2,0,2,'与客户端的通信消息是否压缩，0：不压缩；1：压缩；2：系统自动决定每条消息是否压缩'),(81,'COMM_VALIDATE',1,0,1,'是否对消息进行校验。0：不检验；1：检验, 不记录错误内容；2: 检验, 记录错误消息内容'),(82,'ENABLE_MONITOR',1,0,1,'用于打开或者关闭系统的监控功能。1：打开；0：关闭。'),(83,'ENABLE_FREQROOTS',0,0,3,'指定FAST_POOL的管理方式。0：经典模式，系统启动时装入常用的描述页、索引的根、索引的控制页、指定常驻内存的 表以及索引第二层的节点，之后不再变化；1：动态模式A，系统启动时装入常用的描述页、索引的根、指定常驻内存的表， 后续按负载情况动态装入频繁访问的页；2：动态模式B， 预装入的页同经典模式，后续按负载情况动态装入频繁访问的页； 3：最大模式，试图把数据页全部装入FAST POOL，如果还有富余，则剩下的空闲FAST POOL空间按各文件实际使用长度 按比例预分配，后续不再变化，适合库较小、内存空间大的场景 对于ROLL表空间，最多分配0号文件的前FAST_ROLL_PAGES，其中0、1、2模式下优先分配，3模式下按表空间ID和文件 ID依次分'),(84,'PURGE_DEL_OPT',0,0,2,'事务清理优化');
