  `loadWorkers` int NOT NULL,
  `terminals` int NOT NULL,
  `runTxnsPerTerminal` int NOT NULL,
  `runMins` int NOT NULL,
  `limitTxnsPerMin` int NOT NULL,
  `terminalWarehouseFixed` tinyint(1) NOT NULL,
  `newOrderWeight` int NOT NULL,
  `paymentWeight` int NOT NULL,
  `orderStatusWeight` int NOT NULL,
  `deliveryWeight` int NOT NULL,
  `stockLevelWeight` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
