/*!40000 ALTER TABLE `secondary_para` DISABLE KEYS */;
INSERT INTO `secondary_para` VALUES (1,'MEMORY_N_POOLS',1,0,2048,'共享内存池个数，0 与 1 等价，即共享池不分片。分片时，每池的初始容量为 MEMORY_POOL / MEMORY_N_POOLS，但受最小初始容量为 30M 限制，因此实际分片数可能会小于 MEMORY_N_POOLS，每个池的TARGET 也按此方式由 MEMORY_TARGET 导出'),(2,'KEEP',8,8,1048576,'KEEP 缓冲区大小，以 M 为单位。'),(3,'MULTI_PAGE_GET_NUM',1,1,64,'缓冲区最多一次读取的页面数。'),(4,'SORT_FLAG',0,0,3,'排序机制。\n0：原排序机制，普通排序方式，按照排序缓冲区 SORT_BUF_SIZE 大小获取数据，并进行排序；\n1：新排序机制，大内存排序方式，将大内存排序缓冲区 SORT_BUF_GLOBAL_SIZE 按照内存片大小 SORT_BLK_SIZE\n进行分片，并对每个内存片进行排序，再对整个大内存排序缓冲区的数据进行排序；\n2：采用 SORT_FLAG 为 0 的排序方式的同时，增加递增列，当排序列存在相同值时按递增列进行排序；\n3：采用 SORT_FLAG 为 1 的排序方式的同时，增加递增列，当排序列存在相同值时按递增列进行排序'),(5,'SORT_ADAPTIVE_FLAG',0,0,3,'自适应排序区大小的方式。\n0：不进行自适应；\n1：SORT_FLAG 为 0、2 时，计算待排序数据的实际排序所需要的内存大小，尽可能地分配所需要的内存，如果申请\n失败则减半申请，直到申请成功，并按照实际申请的内存大小代替 SORT_BUF_SIZE 大小进行使用。对进行过刷盘的\n数据进行排序时，计算排序所需要的内存，尽可能地放大排序内存，保证一次排序可以结束排序。SORT_FLAG 为 1、\n3 时，根据 SORT_BUF_GLOBAL_SIZE 和分片内存最大 10000 个的限制，计算 SORT_BLK_SIZE 的最小值，如果\nSORT_BLK_SIZE 小于最小值，则实际按照最小值来分片。对整个大内存排序缓冲区的数据进行排序时，计算排序所\n需要的内存，尽可能地放大排序内存，保证一次排序可以结束排序；\n2：SORT_FLAG 为 0、2 时，按照行数估算待排序数据的实际排序所需要的内存大小，找到最适合排序算法的内存大\n小。当待排序的数据行数超过 50 万时，才开启此优化，数据量太小无需优化；\n3：1 和 2 的组合。当 SORT_FLAG 为 0、2，计算待排序数据的实际排序所需要的内存大小时，采用\nSORT_ADAPTIVE_FLAG 为 2 的按照行数估算待排序所需要内存大小。除此之外的其他情况均保持\nSORT_ADAPTIVE_FLAG 为 1 的方式'),(6,'SORT_BUF_GLOBAL_SIZE',1000,10,4294967294,'新排序机制下，排序全局内存使用上限，以 M 为单位。'),(7,'SORT_BLK_SIZE',1,1,50,'新排序机制下，对数据进行排序的排序缓冲区分片大小，以 M 为单位。'),(8,'HAGR_HASH_SIZE',100000,10000,100000000,'HAGR 操作时，建立 HASH 表的桶个数。'),(9,'MTAB_MEM_SIZE',8,1,1048576,'MTAB 缓存 BDTA 占用内存空间的大小，以 KB 为单位'),(10,'FTAB_MEM_SIZE',0,0,64,'FTAB 缓存 BDTA 占用内存空间的大小，以 KB 为单位。0 表示使用 MTAB，大于 0 时才使用 FTAB。当取值小于 32 时，FTAB_MEM_SIZE 均使用 32'),(11,'MMT_SIZE',0,0,64,'是否使用 MMT。0：不启用；其他有效值：启用，并确定单个映射文件大小，必须小于 MMT_GLOBAL_SIZE。单位 MB'),(12,'MMT_GLOBAL_SIZE',4000,10,1000000,'系统总共使用 MMT 的文件总大小，单位 MB，仅在 MMT_SIZE 大于 0 时有效'),(13,'MMT_FLAG',1,1,2,'MMT 存储数据方式。1：按页存储；2：BDTA 存储。仅在 MMT_SIZE 大于 0 时有效'),(14,'HFS_CACHE_SIZE',160,160,2000,'HUGE 表 I/U/D 时 HDTA_BUFFER 缓存池大小，单位为 MB。'),(15,'VM_STACK_SIZE',256,64,256,'系统执行时虚拟机堆栈大小，以 KB 为单位，堆栈的空间是从操作系统中申请的'),(16,'RT_HEAP_TARGET',8192,8192,10,'会话上用于动态对象存储的 RT_HEAP 最大可扩展到的大小，以 KB 为单位'),(17,'HAGR_DISTINCT_HASH_TABLE_SIZE',10000,10000,100000000,'分组 DISTINCT 操作中 HASH 表的大小（桶数）。'),(18,'CNNTB_HASH_TABLE_SIZE',100,100,100000000,'指定 CNNTB 操作符中创建 HASH 表的大小。'),(19,'GLOBAL_RTREE_BUF_SIZE',100,0,100000,'R 树全局缓冲区大小，以 MB 为单位'),(20,'SINGLE_RTREE_BUF_SIZE',10,0,1000,'单个 R 树的缓冲区大小，以 MB 为单位，必须小于 GLOBAL_RTREE_BUF_SIZE'),(21,'SORT_OPT_SIZE',0,0,1024,'整型/浮点型数据排序优化辅助空间大小，对应待排序数组的最大最小差值，单位 M，取值1M 时对应待排序数组的最大最小差值为 262144，超过则不能使用优化'),(22,'TSORT_OPT',1,0,1,'排序优化选项。0：排序操作一律使用估算的行数分配内存（至少 2M）；1：打开优化，排序操作结果行数较少时，\n使用实际的记录行数分配内存'),(23,'TASK_THREADS',16,1,1000,'任务线程个数'),(24,'SPIN_TIME',4000,0,4000,'线程在不能进入临界区时，自旋的次数'),(25,'WORKER_CPU_PERCENT',0,0,100,'工作线程占 CPU 的比重，仅非 WINDOWS 下有效。0 表示不限制，相当于 100'),(26,'RS_BDTA_FLAG',0,0,2,'是否以 BDTA 形式返回结果集。0：以行为单位返回结果集；2：以 BDTA 形式返回结果集'),(27,'RS_BDTA_BUF_SIZE',32,8,32768,'配置消息长度，单位为 K。'),(28,'MAX_OPT_N_TABLES',6,3,8,'优化器在处理连接时，一次能优化的最大表连接个数'),(29,'MAX_N_GRP_PUSH_DOWN',5,1,1024,'用来控制 GROUP BY 下放优化的最大叶子表节点个数。在 PLACE_GROUP_BY_FLAG 为 2 时生效'),(30,'CTE_OPT_FLAG',1,0,1,'递归 WITH CTE 优化选项，表示相关子查询是否转换为 WITH FUCNTION 优化。支持 HINT。\n取值 0 或 1'),(31,'BATCH_PARAM_OPT',0,0,1,'是否启用批量参数优化，0：不启用；1：启用，默认不启用。当置为 1 时，不返回操作影响的行数'),(32,'CLT_CONST_TO_PARAM',0,0,1,'是否进行语句的常量参数化优化，0：不进行；1：进行'),(33,'FILTER_PUSH_DOWN',0,0,15,'对单表条件是否下放的不同处理方式。0：表示条件不下放；1：表示在新优化器下，对单表过滤条件进行下放\n处理；2：表示在新优化器下对外连接、半连接进行下放条件优化处理；4：语义分析阶段考虑单表过滤条件的\n选择率，超过 0.5 则不下放，由后面进行代价计算选择是否下放，参数值 4 仅在参数取值包含 2 时有效，即将\n参数值设为 6 时有效；8：表示尝试将包含非相关子查询的布尔表达式进行下放。\n支持使用上述有效值的组合值，如 6 表示同时进行 2 和 4 的优化'),(34,'ENABLE_DIST_IN_SUBQUERY_OPT',0,0,7,'IN 子查询的优化方式，0：不优化；1：对 IN 子查询进行去掉子查询的优化；2：IN 子查询中的等值连接转换\n为多个 IN；4：IN 子查询中移除与外表相同的内表\n支持使用上述有效值的组合值，如 5 表示同时进行 1 和 4 的优化'),(35,'USE_HAGR_FLAG',0,0,1,'当带有 DISTINCT 的集函数不能使用 SAGR 操作符时，是否使用 HAGR，0：不使用；1：使用'),(36,'DTABLE_PULLUP_FLAG',1,0,1,'是否在语法分析阶段对派生表进行上拉优化处理，0：不优化；1：优化'),(37,'VIEW_PULLUP_FLAG',0,0,63,'是否对视图进行上拉优化，把视图转换为其原始定义，消除视图。0：不进行视图上拉优化；1：对不包含别名和同名列的视图进行上拉优化；2：对包含别名和同名列的视图也进行上拉优化；4：强制允许带变量的查询语句进行视图上拉优化，有可能造成结果集错误；8：不对 LEFT JOIN 的右孩子\\RIGHT JOIN 的左孩子\\FULL JOIN 左右孩子进行上拉；16：不对 LEFT JOIN 的左孩子进行上拉；32：视图上拉后，从视图符号表删除不被引用的列\n支持使用上述有效值的组合值，如 3 表示同时进行 1 和 2 的优化'),(38,'VIEW_PULLUP_MAX_TAB',7,1,16,'对视图进行上拉优化支持的表的个数。'),(39,'FROM_OPT_FLAG',0,0,1,'控制一些涉及 FROM 项的优化 0：不优化；1：尝试将 FROM 项替换为单个 DUAL 表'),(40,'REFED_EXISTS_OPT_FLAG',0,0,3,'是否把相关 EXISTS 优化为非相关 IN 查询。0：否；1：是；2：特殊场景下，通过将相关表+DISTINCT 构造\n为派生表添加到子查询中，将相关 EXISTS 转换为非相关 IN\n支持使用上述有效值的组合值，如 3 表示同时进行 1 和 2 的优化'),(41,'REFED_OPS_SUBQUERY_OPT_FLAG',0,0,7,'是否将 OP ALL/SOME/ANY 相关子查询进行转换处理。0：否；1：转换为 EXISTS 相关子查询；2：将包含\nPARTITION JOIN 连接的相关子查询转换为 EXISTS 相关子查询（已废弃，不进行转换）；4：转换为包含分\n析函数的派生表\n支持使用上述有效值的组合值，如 3 表示同时进行 1 和 2 的优化，当组合值中包含 1 且不包含 4 时，优先按照\n值为 1 进行转换处理，当组合值中包含 4 时优先按照值为 4 进行转换处理'),(42,'MAX_PHC_BE_NUM',512,512,20480000,'优化阶段存放临时布尔表达式的个数。'),(43,'PARTIAL_JOIN_EVALUATION_FLAG',1,0,1,'是否对去除重复值操作的下层连接进行转换优化。0：不优化；1：优化\n此参数仅在参数 OPTIMIZER_MODE 为 1 时才有效'),(44,'USE_FK_REMOVE_TABLES_FLAG',1,0,1,'是否利用外键约束消除冗余表，支持多列主键。0：不启用；1：启用'),(45,'USE_FJ_REMOVE_TABLE_FLAG',0,0,1,'是否启用使用过滤表消除表及自连接消除优化。0：不启用；1：启用；2：等值条件的左右两边是不同的表时\n才进行优化'),(46,'USE_HTAB',0,0,1,'表示计划中是否能使用 HTAB。0：否；1：是'),(47,'SEL_ITEM_HTAB_FLAG',0,0,15,'当 USE_HTAB=1 时才有效。\n当查询项中有相关子查询时，控制是否做 HTAB 优化及优化的方式。0：不生成 HTAB；1：查询项之后生成 HTAB，\n需包含单表过滤条件；2：查询项之后生成 HTAB，无需单表过滤条件；4：WHERE 条件之前生成 HTAB（需同\n时设置参数为 8）；8：包括 GROUP 条件在内，整体生成 HTAB'),(48,'OR_CVT_HTAB_FLAG',1,0,2,'当 USE_HTAB=1 时才有效。\n当查询条件 OR 中含有公共因子时，是否允许使用 HTAB 来进行优化。0：不使用；1：使用；2：增强 OR 表达\n式转换为 HTAB 条件检查，当存在嵌套连接时，不生成 HTAB，以避免缓存过多数据影响性能'),(49,'OR_NBEXP_CVT_CASE_WHEN_FLAG',0,0,1,'是否将OR 转化为CASE WHEN THEN ELSE END语句。0：不转换；1：转换'),(50,'NONCONST_OR_CVT_IN_LST_FLAG',0,0,1,'是否开启 IN LIST 优化：将不含有常量的 OR 表达式转换成 IN LIST。0 表示不开启，1 表示开启'),(51,'OPT_OR_FOR_HUGE_TABLE_FLAG',1,0,1,'是否使用 HFSEK 优化 HUGE 表中列的 OR 过滤条件。0：不使用；1：使用'),(52,'SUBQ_CVT_SPL_FLAG',1,0,31,'控制相关子查询的实现方式，0：不优化；1：使用 SPL2 方式实现相关子查询；2：DBLINK 相关子查询是否转\n换为函数，由参数 ENABLE_DBLINK_TO_INV 取值决定 4：将多列 IN 转换为 EXISTS；8：将引用列转换为\n变量 VAR；16：用临时函数替代查询项中的相关查询表达式\n支持使用上述有效值的组合值，如 5 表示同时进行 1 和 4 的优化'),(53,'ENABLE_RQ_TO_SPL',1,0,1,'是否将相关子查询转换为 SPL2 方式，0：不优化；1：优化'),(54,'MULTI_IN_CVT_EXISTS',0,0,1,'多列 IN 是否转换为等价的 EXISTS 过滤。0：不转换；1：转换'),(55,'PRJT_REPLACE_NPAR',1,0,1,'是否将引用列转换为变量 VAR，并替换查询表达式中的引用列，0：不优化；1：优化'),(56,'ENABLE_RQ_TO_INV',0,0,2,'相关查询表达式是否转换为函数方式实现。0：不转换；1：转换；2：系统根据实际情况决定是否转换'),(57,'SUBQ_EXP_CVT_FLAG',0,0,255,'是否将带有聚集函数且没有 GROUP BY 的相关查询表达式优化为非相关查询表达式。\n0：使用普通的去相关性处理；\n1：带有聚集函数且没有 GROUP BY 的相关查询表达式优化为非相关查询表达式；\n2：将子查询列均来自上层查询且子查询中不包含层次查询、ROWNUM、TOP 的相关子查询的 FROM 项改写为\n(SELECT TOP 1 1 FROM ...)派生表，减少中间结果集；\n8：将 EXISTS 子查询的查询项转换为常量 0，兼容 ORACLE 处理方式，同时优化子查询对查询项的处理过程。\n如果子查询为集合查询，则不进行转换；\n16：通过原始语句判断查询表达式是否相同；\n32：带有聚集函数且没有 GROUP BY 的相关查询表达式在 OP_NBEXP 中(只有一层)，且聚集函数没有 COUNT，\n那么相关拉平可以使用 CROSS JOIN 替换 LEFT JOIN；\n64：消除没被使用到的非相关查询表达式或者相关列已在同层 DISTINCT 子句中的相关查询表达式查询项；\n128：对于 DISTINCT 查询表达式，在不影响 DISTINCT 结果情况下，将查询表达式放在 DISTINCT 之后做。\n支持使用上述有效值的组合值，如 3 表示同时进行 1 和 2 的优化。SUBQ_EXP_CVT_FLAG 同时包含 1 和 32\n时，1 的优先级更高'),(58,'USE_REFER_TAB_ONLY',0,0,1,'处理相关子查询时是仅将相关的表下放，或者连同上方的 SEMI/HASH JOIN 一起下放。0：一起下放；1：仅\n下放相关表'),(59,'IN_LIST_AS_JOIN_KEY',0,0,1,'搜索多表连接方式时，对于索引连接（INDEX JOIN）的探测，NEXP_IN_LST 表达式类型可以作为多表连接\n的 KEY。\n取值范围：\n0：表示搜索多表连接方式时，对于索引连接（INDEX JOIN）的探测，NEXP_IN_LST 不可以作为连接 KEY；\n1：表示搜索多表连接方式时，对于索引连接（INDEX JOIN）的探测，把 NEXP_IN_LST 当做普通等值 KEY\n的处理方式来生成 INDEX JOIN 的连接 KEY。'),(60,'OUTER_JOIN_INDEX_OPT_FLAG',0,0,1,'外连接优化为索引连接的优化开关。1：优化；0：不优化。'),(61,'OUTER_JOIN_FLATING_FLAG',0,0,1,'优化外连接。\n0：不启用优化；\n1：启用优化，例如，使得类似这样的连接 A LEFT (B CROSS C) ON A.C1=B.C1 优化为 A LEFT (B JOIN \n(DISTINCT A) ON A.C1=B.C1 CROSS C) ON A.C1=B.C1 ，相当于把 A 和 B 的过滤器平坦化到了下层\n查询中，使得 B 获取的中间结果较小'),(62,'TOP_ORDER_OPT_FLAG',0,0,15,'优化带有 TOP 和 ORDER BY 子句的查询，使得 SORT 操作符可以省略。优化的效果是尽量使得 ORDER BY 的\n排序列所对应的基表可以使用包含排序列的索引，从而可以移除排序 SORT 操作符，减少排序操作。如果排序\n列不属于同一个基表，或者排序列不是基表列，则无法进行优化。取值：\n0：不启用该优化；\n1：对最优索引进行优化；\n2：优先选择与排序列一致的可以消除排序的索引进行优化；\n4：若查询项中包含 TOP 子句和集函数，且查询语句中不存在分组项，则移除 TOP 子句。仅当 TOP 值不为 0\n时进行该优化；\n8:当前就有计划是 CSCN 的 TOP_ORDER 语句，根据估算需要 BLKUP 的行数判断是否依然使用 TOP_ORDER 优\n化\n支持使用上述有效值的组合值，如 3 表示同时进行 1 和 2 的优化'),(63,'TOP_ORDER_ESTIMATE_CARD',300,0,4294967294,'TOP_ORDER_OPT_FLAG=1/2 命中优化时，设置叶子节点的预估扫描行数。下层操作符不是简单的 BT 时，如\n果优化器预估行数不准，可帮助优化器调整，以便选择最优计划。'),(64,'TOP_DIS_HASH_FLAG',1,0,2,'是否通过禁用 HASH JOIN 方式来优化 TOP 查询，取值：\n0：不优化；\n1：当 OPTIMIZER_MODE 为 0 时，TOP 下方连接禁用 HASH JOIN；当 OPTIMIZER_MODE 为 1 时，TOP 下方\n最近的连接倾向于不使用 HASH JOIN；\n2：当 OPTIMIZER_MODE 为 0 时，TOP 下方连接禁用 HASH JOIN；当 OPTIMIZER_MODE 为 1 时，TOP 下方\n所有连接都倾向于不使用 HASH JOIN'),(65,'ENABLE_RQ_TO_NONREF_SPL',0,0,7,'相关查询表达式转化为非相关查询表达式，目的在于相关查询表达式的执行处理由之前的平坦化方式转化为一\n行一行处理，类似 ORACLE 的每行处理机制。\n0：不启用该优化；1：对查询项中出现的相关子查询表达式进行优化处理；2：对查询项和 WHERE 表达式中出\n现的相关子查询表达式进行优化处理；4：相关查询采用 SPL 方式去相关性后，可以作为单表过滤条件\n支持使用上述有效值的组合值，如 3 表示同时进行 1 和 2 的优化'),(66,'ENABLE_CHOOSE_BY_ESTIMATE_FLAG',0,0,7,'通过估算引用表/表连接的结果集行数决定是否进行去相关性优化。\n0：不进行行数估算；1：引用单表且 ENABLE_RQ_TO_NONREF_SPL 不为 0 时进行行数估算，若行数过大则\n不进行 ENABLE_RQ_TO_NONREF_SPL 为对应值时的优化；2：引用单表且 SUBQ_EXP_CVT_FLAG=1 时进行\n行数估算，若行数过大则不进行 SUBQ_EXP_CVT_FLAG=1 时的优化；4：引用表连接且\nENABLE_RQ_TO_NONREF_SPL 不为 0 时进行行数估算，若行数过大则不进行 ENABLE_RQ_TO_NONREF_SPL\n为对应值时的优化。由于需要通过动态采样的方式估算表连接后的结果集行数，因此第一次执行时速度可能较\n慢\n支持使用上述有效值的组合值，如 3 表示同时进行 1 和 2 的优化'),(67,'OPTIMIZER_MODE',1,0,1,'DM 优化器的模式，0：老优化器模式；1：新优化器模式'),(68,'NEW_MOTION',0,0,1,'是否使用代价计算来决定使用的通讯操作符，0：否；1：是'),(69,'LDIS_NEW_FOLD_FUN',0,0,1,'是否开启 LOCAL DISTRIBUTE 操作符使用与 MPP DISTRIBUTE 操作符不同的函数来计算哈希值。0：否；1：\n是'),(70,'DYNAMIC_CALC_NODES',0,0,1,'是否根据数据量设置 LOCAL DISTRIBUTE\\ MPP DISTRIBUTE 操作符不同的并行度\\节点数。0：否；1：是'),(71,'OPTIMIZER_MAX_PERM',7200,1,4294967294,'控制计划探测过程中的最大排列数，如果大于该阙值，则减少相应的排列，减少探测计划的时间'),(72,'ENABLE_INDEX_FILTER',0,0,2,'是否进行索引过滤优化，可取值为 0、1、2。\n0 不进行优化；\n1 使用索引过滤优化，如果过滤条件涉及的列包含在索引中，那么索引进行 SSEK2 后就可以使用此过滤条件，\n可以减少中间结果集；\n2 在取值为 1 的基础上，将 IN 查询列表转换为 HASH RIGHT SEMI JOIN。'),(73,'OPTIMIZER_DYNAMIC_SAMPLING',0,0,12,'当统计信息不可用时是否启用动态统计信息。取值范围：0~12。0：不启用；1~10：启用，采用率 10%~100%；\n11：启用，由优化器确定采样率（0.1%~99.9%）；12：同 11，但收集的结果会持久化保存'),(74,'HASH_CMP_OPT_FLAG',0,0,15,'是否启用静态哈希表的优化。0：不启用优化；1：分组中的 DISTINCT 开启此优化；2：对 HASH 连接启用该\n优化；4：对 HAGR 分组计算启用该优化；8：DISTINCT 操作开启此优化。\n支持使用上述有效值的组合值，如 5 表示同时进行 1 和 4 的优化'),(75,'OUTER_OPT_NLO_FLAG',0,0,7,'是否进行外连接和内连接的相关优化。0：不优化；1：满足条件时，将外连接转换为嵌套外连接进行优化；2：满足条件时，将内连接转换为嵌套连接+VAR 方式进行优化；4：打开外连接操作符 HLO/HRO 只返回不满足条件值的优化。\n取值 1、2 仅在 OPTIMIZER_MODE = 0 时生效。\n支持使用上述有效值的组合值，如 5 表示同时进行 1 和 4 的优化'),(76,'DISTINCT_USE_INDEX_SKIP',2,0,2,'DISTINCT 列是否使用索引跳跃扫描（单列索引或复合索引）。专门用于 SQL 语句中有 DISTINCT 的场景，DISTINCT 列的查询的一种优化方式，在索引上跳跃着扫描。0：不使用；1：强制使用；2：根据代价选择是否使用。\n该参数只在 OPTIMIZER_MODE=1 时有效'),(77,'USE_INDEX_SKIP_SCAN',0,0,2,'是否使用复合索引跳跃扫描。专门用于 WHERE 子句等值条件的查询列中包含了复合索引的列，但该列又不是复合索引的前导列，这种情况下，选择是否使用复合索引跳跃扫描。和 INDEX_SKIP_SCAN_RATE 搭配使用。\n0：不使用；\n1：根据代价选择是否使用。通过代价计算选择，倾向于选择前导列 DISTINCT 值少，搜索列 DISTINCT 值较\n多的索引；\n2：强制使用。只要能够找到索引可以使用跳跃扫描，就强制使用'),(78,'OP_SUBQ_CVT_IN_FLAG',1,0,1,'当查询条件为=(SUBQUERY)，是否考虑转换为等价的 IN(SUBQUERY)。0：不转换；1：转换'),(79,'ENHANCED_SUBQ_MERGING',0,0,3,'是否对子查询进行合并优化，0：不优化；1：对 WHERE 子句和 JOIN ON 子句中存在包含关系的子查询进行合并优化；2：对 UNION 和 INTERSECT 等集合运算中相同的子查询进行合并优化\n支持使用上述有效值的组合值，如 3 表示同时进行 1、2 的优化'),(80,'HLSM_FLAG',1,1,3,'控制多列非相关 NOT IN 的查询实现方式，1：当数据量较大，HASH BUF 放不下时，采用 MTAB 方式处理；2：当数据量较大，HASH BUF 放不下时，采用 B 树方式处理，使用细粒度扫描；3：当数据量较大，HASH BUF放不下时，采用 B 树方式处理，使用粗粒度扫描'),(81,'DEL_HP_OPT_FLAG',0,0,31,'控制分区表的操作优化，0：不优化；1：打开分区表 DELETE 优化；2：控制范围分区表创建的优化处理，转\n换为数据流方式实现；4：允许语句块中的间隔分区表自动扩展；8：开启对 TRUNCATE 分区表的优化处理；\n16：完全刷新时删除老数据使用 DELETE 方式支持使用上述有效值的组合值，如 7 表示同时进行 1、2、4 的优化'),(82,'OPTIMIZER_OR_NBEXP',0,0,31,'OR 表达式的优化方式。0：不优化；1：生成 UNION_FOR_OR 操作符时，优化为无 KEY 比较方式；2：OR 表\n达式优先考虑整体处理方式；4：相关子查询的 OR 表达也优考虑整体处理方式；8：OR 布尔表达式的范围合并优化；16：同一列上同时存在常量范围过滤和 IS NULL 过滤时的优化，如 C1 > 5 OR C1 IS NULL。\n支持使用上述有效值的组合值，如 7 表示同时进行 1、2、4 的优化'),(83,'CNNTB_OPT_FLAG',0,0,255,'是否使用优化的层次查询执行机制。0：不使用；1：强制使用；2：优化器自动决定是否使用；4：层次查询不\n支持并行；8：检查层次查询的表达式是否包含 ROWNUM，若包含则报错；16：层次查询的条件包含 OR 时仍尝试使用优化，且将 OR 连接的条件表达式当做整体处理；32：根据 PRIOR 关联列的 DISTINCT 值与统计信息中总行数的比例自适应选择执行机制；64：对于简单条件（如：DUAL.LEVEL<=10）准确估算层次查询行数；128：对层次查询的执行计划节点分析时，如果右孩子包含参数无法生成临时表，依然向下分析右孩子的子节点能否生成临时表以提升性能。\n支持使用上述有效值的组合值，如 31 表示同时进行 1、2、4、8、16 的优化'),(84,'HAGR_HASH_ALGORITHM_FLAG',0,0,1,'HAGR 中 HASH 算法选择标记。0：按照移位方式计算；1：按照异或方式计算'),(85,'DIST_HASH_ALGORITHM_FLAG',0,0,1,'DISTINCT 中 HASH 算法选择标记。0：按照移位方式计算；1：按照异或方式计算'),(86,'ENABLE_JOIN_FACTORIZATION',0,0,1,'是否启用连接分解，即 UNION ALL 分支间存在公共部分时是否进行公因子提取。0：不启用；1：启用'),(87,'ENABLE_PARTITION_WISE_OPT',0,0,1,'是否利用水平分区表的分区信息进行排序、分组的计划优化，即在满足条件的情况下对每个子表单独排序、分\n组，或者进行子表间的归并排序。0：不启用；1：启用'),(88,'PLACE_GROUP_BY_FLAG',0,0,3,'在含有集函数的查询中，是否允许先分组减少数据量后再进行连接。\n0：不允许；\n1：允许，要求是两个表的连接，且基函数的参数只能来自一张表；\n2：允许，2 是 1 的加强，允许有多张表的连接，且基函数的参数可来自多张表，与MAX_N_GRP_PUSH_DOWN\n配合使用。\n此参数仅在 OPTIMIZER_MODE=1 时有效'),(89,'ENABLE_NEST_LOOP_JOIN_CACHE',0,0,3,'是否对嵌套循环连接进行优化以及如何优化，0：不优化；1：考虑缓存嵌套循环连接的中间结果以加速执行；\n2：嵌套循环连接执行时优先探测右孩子节点的数据\n支持使用上述有效值的组合值，如 3 表示同时进行 1、2 的优化'),(90,'VIEW_OPT_FLAG',1,0,1,'视图优化处理参数。0：关闭优化；1：允许不可更新视图输出 ROWID'),(91,'ENABLE_ADJUST_NLI_COST',1,0,1,'是否允许系统自动对嵌套连接的代价进行增大调整。0：不允许；1：不允许'),(92,'ENABLE_ADJUST_DIST_COST',0,0,2,'是否对索引连接的 DISTINCT 值估算行数进行优化调整。0：不优化；1：若索引连接计划中左孩子为 DISTINCT\n或 GROUP 类型，则使用左孩子的估算行数和右孩子的估算行数相乘作为连接后的 DISTINCT 行数值；2：索引\n连接计划中，使用左孩子的估算行数除以 3 和右孩子的估算行数相乘作为连接后的 DISTINCT 值'),(93,'TRX_CMTARR_SIZE',10,3,1000,'提交状态事务数组的大小，仅当 TRX_VIEW_MODE 为 1 时有效。单位为百万。此参数设置越大，内存消耗越多，当应用为高并发，单位时间内事务完成数量大时，可将此参数值设大'),(94,'OLAP_FLAG',2,0,2,'启用联机分析处理，0：不启用；1：启用；2：不启用，同时倾向于使用索引范围扫描'),(95,'TEMP_SIZE',10,10,1048576,'默认创建的临时表空间大小，以 M 为单位。'),(96,'PLN_DICT_HASH_THRESHOLD',20,1,67108864,'仅当 CACHE_POOL_SIZE 参数值大于等于此参数值时，才开启缓存计划的字典关联登记，单位：MB'),(97,'STAT_COLLECT_SIZE',10000,0,10000000,'统计信息收集时，样本的最小行数。'),(98,'STAT_ALL',0,0,4,'在估算分区表行数时，控制一些优化。0：不采样所有分区子表；1：采样所有分区子表；2：优先采用统\n计信息中的行数；4：水平分区表不使用主表统计信息而使用叶子表统计信息。\n支持使用上述有效值的组合值，如 3 表示优先采用统计信息中的行数，如果没有找到对应统计信息，则去\n采样所有分区子表。'),(99,'MAX_PARALLEL_DEGREE',1,0,128,'用来设置默认并行任务个数。缺省值 1，表示无并行任务。当 PARALLEL_POLICY 值为 1 时该参数值才有效'),(100,'PARALLEL_POLICY',0,0,2,'用来设置并行策略。取值范围：0、1 和 2，缺省为 0。其中，0 表示不支持并行；1 表示自动并行模式；2表示手动并行模式'),(101,'PARALLEL_THRD_NUM',10,1,1024,'用来设置并行工作线程个数。'),(102,'PARALLEL_MODE_COMMON_DEGREE',1,1,1024,'并发模式程度。此值越大，扫描代价将越大，越倾向于使用索引连接而不是哈希连接，需酌情使用。'),(103,'PUSH_SUBQ',0,0,7,'是否下放子查询使先做。0：始终不下放；1：相关子查询且不存在单表过滤条件时下放；2：相关子查询\n始终下放；4：非相关子查询下放'),(104,'HFINS_PARALLEL_FLAG',0,0,2,'是否启动HUGE表查询插入优化。0：否；1：对非HUGE分区表进行优化；2：对HUGE分区表也进行优化'),(105,'HFINS_MAX_THRD_NUM',100,4,200,'HUGE表查询插入优化时并行的最大线程数'),(106,'TMP_DEL_OPT',1,0,1,'是否对临时表删除进行优化。0：不优化；1：如果不要求临时表可回滚，则对于无过滤条件的临时表删除\n语句，在执行删除时直接清除其临时段数据'),(107,'STAT_OPT_FLAG',0,0,1,'生成统计信息的优化。0：不优化；1：生成统计信息时不存储左孩子的数据，以在某些场景表实现性能的\n提升'),(108,'LOCK_TID_MODE',1,0,1,'SELECT FOR UPDATE 封锁方式。0：结果集记录小于 100 行，直接封锁 TID，否则升级为表锁； 1：不升\n级表锁,一律使用 TID 锁'),(109,'LOCK_TID_UPGRADE',0,0,1,'0：事务启动时，用自己的事务号生成的TID锁，以X封锁；DELETE/UPDATE记录触发的TID锁，优先使用S\n封锁，只有在多个事务同时更新同一行记录场景下，升级为X锁。1：所有TID锁以X方式封锁'),(110,'TRX_DICT_LOCK_NUM',64,1,100000,'开启LOCK_DICT_OPT优化场景下最多可缓存的IX/IS类型字典锁对象数量。'),(111,'FINS_LOCK_MODE',1,0,2,'快速插入封锁方式。0：保持表锁不放；1：采用NOWAIT方式尝试封锁，当前数据处理完后立即释放锁；2：\n采用超时方式尝试封锁，当前数据处理完后立即释放锁'),(112,'SEL_RATE_EQU',0,0,1,'等于谓词的选择率'),(113,'SEL_RATE_SINGLE',0,0,1,'非等于谓词的选择率');
